import json
m = json.load(open('/workspace/incident/dataset/manifest.json'))
c = json.load(open('/workspace/incident/dataset/catalog.json'))
print('manifest rows:', len(m['rows']), 'schema:', m.get('schema_version'))
print('catalog rows:', len(c['rows']), 'schema:', c.get('schema_version'))
import collections
for name, d in (('manifest', m), ('catalog', c)):
    paths = [r['path'] for r in d['rows']]
    pref = collections.Counter(p.split('/')[0] + '/' + p.split('/')[1] for p in paths)
    print(name, pref)
    splits = collections.Counter((r['split'], r['difficulty']) for r in d['rows'])
    print(name, splits)
# same ids?
mids = {r['id'] for r in m['rows']}; cids = {r['id'] for r in c['rows']}
print('same ids:', mids == cids, len(mids), len(cids))
# path diffs
mm = {r['id']: r['path'] for r in m['rows']}
cc = {r['id']: r['path'] for r in c['rows']}
diff = {k: (mm[k], cc[k]) for k in mm if mm[k] != cc.get(k)}
print('path diffs:', len(diff))
for k, v in list(diff.items())[:5]:
    print(k, v)
# sha diffs
ms = {r['id']: r['sha256'] for r in m['rows']}
cs = {r['id']: r['sha256'] for r in c['rows']}
sdiff = {k for k in ms if ms[k] != cs.get(k)}
print('sha diffs:', len(sdiff), list(sdiff)[:5])
