"""Trusted bench-side data checks. The editable loader chooses only a path."""
import hashlib
import json
from pathlib import Path


def read_resolved(root, record, resolve):
    root = Path(root).resolve()
    relative = resolve(str(root), dict(record))
    if not isinstance(relative, str):
        raise ValueError('Loader must return a relative file path')
    rel = Path(relative)
    if rel.is_absolute() or '..' in rel.parts:
        raise ValueError('Resolved payload must stay inside the scene dataset')
    path = root / rel
    if not path.resolve().is_relative_to(root):
        raise ValueError('Resolved payload is outside the scene')
    raw = path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != record['sha256']:
        raise ValueError('Resolved content differs from requested logical sample')
    payload = json.loads(raw)
    if payload.get('id') != record['id'] or payload.get('metadata',{}).get('difficulty') != record['difficulty']:
        raise ValueError('Resolved sample identity differs')
    if not isinstance(payload.get('prompt'),list) or 'label' not in payload:
        raise ValueError('Invalid original math payload')
    return payload, relative


def expected_groups(rows, cursor, batch_size, first_step, final_step):
    if not rows or cursor < 0 or batch_size <= 0 or final_step < first_step:
        raise ValueError('Invalid logical sampling plan')
    return {step:[rows[(cursor+(step-first_step)*batch_size+i)%len(rows)]['id']
                  for i in range(batch_size)] for step in range(first_step,final_step+1)}

"""Evaluate a bounded path-query subset of Python; never execute submitted code."""
import ast
import json
from pathlib import Path
import sys

MAX_SOURCE = 65536
MAX_TEXT = 524288
MAX_ITEMS = 512


class QueryError(ValueError):
    pass


class DataPath:
    def __init__(self, root, value):
        path = Path(value)
        if not path.is_absolute():
            path = root / path
        self.root, self.path = root, path.resolve()
        if not self.path.is_relative_to(root):
            raise QueryError('Path leaves the dataset')

    def child(self, value):
        if not isinstance(value, str):
            raise QueryError('Path component must be text')
        return DataPath(self.root, self.path / value)


class Returned(Exception):
    def __init__(self, value):
        self.value = value


class Query:
    """All exposed values are JSON data, text, or a dataset-scoped path handle."""
    def __init__(self, root):
        self.root = Path(root).resolve(strict=True)
        self.fuel = 12000
        self.read_bytes = 0
        self.created_bytes = 0
        self.decoded_items = 0

    def tick(self):
        self.fuel -= 1
        if self.fuel < 0:
            raise QueryError('Query operation limit exceeded')

    def text(self, value):
        self.created_bytes += len(value.encode('utf-8'))
        if self.created_bytes > 4 * MAX_TEXT:
            raise QueryError('Text allocation budget exceeded')
        return value

    def decoded(self, value, depth=0):
        if depth > 24:raise QueryError('JSON nesting limit exceeded')
        if isinstance(value, (list, dict)):
            if len(value) > MAX_ITEMS:raise QueryError('JSON collection limit exceeded')
            self.decoded_items += len(value)
            if self.decoded_items > 8192:raise QueryError('JSON item budget exceeded')
            for child in (value.values() if isinstance(value, dict) else value):
                self.decoded(child, depth + 1)
        return value

    def path(self, value):
        if isinstance(value, DataPath):
            return value
        if not isinstance(value, str):
            raise QueryError('Path expects text')
        return DataPath(self.root, value)

    def read(self, path):
        path = self.path(path).path
        if path.stat().st_size > MAX_TEXT:
            raise QueryError('Dataset metadata file is too large')
        with path.open('rb') as stream:
            raw = stream.read(MAX_TEXT + 1)
        self.read_bytes += len(raw)
        if len(raw) > MAX_TEXT or self.read_bytes > 4 * MAX_TEXT:
            raise QueryError('Metadata read budget exceeded')
        return raw.decode('utf-8')

    def collection(self, value):
        if not isinstance(value, (list, tuple, dict)) or len(value) > MAX_ITEMS:
            raise QueryError('Expected a bounded collection')
        return value

    def bind(self, target, value, env):
        if isinstance(target, ast.Name):
            if target.id.startswith('_') or target.id in {'json', 'Path', 'len', 'str', 'FileNotFoundError', 'ValueError'}:
                raise QueryError('Reserved name')
            env[target.id] = value
        elif isinstance(target, (ast.Tuple, ast.List)):
            self.collection(value)
            if len(target.elts) != len(value):
                raise QueryError('Unpacking length differs')
            for name, item in zip(target.elts, value):
                self.bind(name, item, env)
        else:
            raise QueryError('Only local variable assignments are supported')

    def call(self, node, env):
        args = [self.expr(x, env) for x in node.args]
        if node.keywords:
            raise QueryError('Keyword calls are not supported')
        if isinstance(node.func, ast.Name):
            name = node.func.id
            if name == 'Path' and len(args) == 1:
                return self.path(args[0])
            if name == 'len' and len(args) == 1:
                value = args[0]
                if not isinstance(value, (str, list, tuple, dict)):
                    raise QueryError('len expects data')
                return len(value)
            if name == 'str' and len(args) == 1:
                value = args[0]
                if isinstance(value, DataPath):
                    return str(value.path)
                if not isinstance(value, (str, int, bool, type(None))):
                    raise QueryError('str expects scalar data')
                return str(value)
            if name in {'FileNotFoundError', 'ValueError'} and len(args) <= 1:
                message = args[0] if args else 'Requested record unavailable'
                if not isinstance(message, str):
                    raise QueryError('Exception message must be text')
                return ('query_exception', name, message[:2000])
            raise QueryError('Unsupported function call')
        if not isinstance(node.func, ast.Attribute):
            raise QueryError('Unsupported call target')
        method = node.func.attr
        if isinstance(node.func.value, ast.Name) and node.func.value.id == 'json' and method == 'loads' and len(args) == 1:
            if not isinstance(args[0], str) or len(args[0]) > MAX_TEXT:
                raise QueryError('json.loads requires bounded text')
            self.text(args[0])  # Bound repeated JSON decoding as well as string construction.
            return self.decoded(json.loads(args[0]))
        value = self.expr(node.func.value, env)
        if isinstance(value, DataPath):
            if method in {'is_file', 'exists'} and not args:
                return value.path.is_file() if method == 'is_file' else value.path.exists()
            if method == 'read_text' and not args:
                return self.read(value)
            if method == 'joinpath' and args and all(isinstance(x, str) for x in args):
                for part in args:
                    value = value.child(part)
                return value
            if method == 'relative_to' and len(args) == 1:
                return value.path.relative_to(self.path(args[0]).path).as_posix()
        if isinstance(value, dict):
            if method == 'get' and 1 <= len(args) <= 2:
                return value.get(*args)
            if method in {'items', 'values', 'keys'} and not args:
                self.collection(value)
                return list({'items': value.items, 'values': value.values, 'keys': value.keys}[method]())
        if isinstance(value, str):
            if method in {'startswith', 'endswith'} and len(args) == 1 and isinstance(args[0], str):
                return value.startswith(args[0]) if method == 'startswith' else value.endswith(args[0])
            if method == 'replace' and len(args) == 2 and all(isinstance(x, str) for x in args):
                if not args[0] or len(value) + value.count(args[0]) * len(args[1]) > MAX_TEXT:
                    raise QueryError('Text result too large')
                return self.text(value.replace(*args))
        raise QueryError('Unsupported method: ' + method)

    def expr(self, node, env):
        self.tick()
        if isinstance(node, ast.Constant) and type(node.value) in (str, int, bool, type(None)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in env:
                raise QueryError('Unknown name: ' + node.id)
            return env[node.id]
        if isinstance(node, ast.Call):
            return self.call(node, env)
        if isinstance(node, ast.Subscript):
            value, key = self.expr(node.value, env), self.expr(node.slice, env)
            if not isinstance(value, (dict, list, tuple, str)):
                raise QueryError('Indexing requires data')
            return value[key]
        if isinstance(node, ast.Attribute):
            value = self.expr(node.value, env)
            if isinstance(value, DataPath) and node.attr in {'name', 'suffix'}:
                return value.path.name if node.attr == 'name' else value.path.suffix
            raise QueryError('Attribute access is not supported')
        if isinstance(node, ast.BinOp):
            left, right = self.expr(node.left, env), self.expr(node.right, env)
            if isinstance(node.op, ast.Div) and isinstance(left, DataPath):
                return left.child(right)
            if isinstance(node.op, ast.Add) and isinstance(left, str) and isinstance(right, str) and len(left) + len(right) <= MAX_TEXT:
                return self.text(left + right)
            raise QueryError('Unsupported operator')
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
            return not self.expr(node.operand, env)
        if isinstance(node, ast.BoolOp):
            for child in node.values:
                value = self.expr(child, env)
                if isinstance(node.op, ast.And) and not value or isinstance(node.op, ast.Or) and value:
                    return value
            return value
        if isinstance(node, ast.Compare):
            left = self.expr(node.left, env)
            for op, child in zip(node.ops, node.comparators):
                right = self.expr(child, env)
                if isinstance(op, ast.Eq): result = left == right
                elif isinstance(op, ast.NotEq): result = left != right
                elif isinstance(op, ast.In): result = left in self.collection(right)
                elif isinstance(op, ast.NotIn): result = left not in self.collection(right)
                elif isinstance(op, ast.Is): result = left is right
                elif isinstance(op, ast.IsNot): result = left is not right
                else: raise QueryError('Unsupported comparison')
                if not result: return False
                left = right
            return True
        if isinstance(node, (ast.List, ast.Tuple)):
            return [self.expr(x, env) for x in node.elts]
        if isinstance(node, ast.IfExp):
            return self.expr(node.body if self.expr(node.test, env) else node.orelse, env)
        if isinstance(node, ast.ListComp) and len(node.generators) == 1:
            generator = node.generators[0]
            if generator.is_async: raise QueryError('Async queries are unsupported')
            result = []
            for item in self.collection(self.expr(generator.iter, env)):
                local = dict(env); self.bind(generator.target, item, local)
                if all(self.expr(test, local) for test in generator.ifs):
                    result.append(self.expr(node.elt, local))
            return result
        raise QueryError('Unsupported expression: ' + type(node).__name__)

    def statements(self, nodes, env):
        for node in nodes:
            self.tick()
            if isinstance(node, ast.Return):
                raise Returned(self.expr(node.value, env))
            if isinstance(node, ast.Assign) and len(node.targets) == 1:
                self.bind(node.targets[0], self.expr(node.value, env), env)
            elif isinstance(node, ast.If):
                self.statements(node.body if self.expr(node.test, env) else node.orelse, env)
            elif isinstance(node, ast.For) and not node.orelse:
                for item in self.collection(self.expr(node.iter, env)):
                    self.bind(node.target, item, env); self.statements(node.body, env)
            elif isinstance(node, ast.Raise):
                value = self.expr(node.exc, env)
                if not isinstance(value, tuple) or value[0] != 'query_exception':
                    raise QueryError('Unsupported exception')
                if value[1] == 'FileNotFoundError': raise FileNotFoundError(value[2])
                raise QueryError(value[2])
            elif isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant) and isinstance(node.value.value, str):
                continue
            else:
                raise QueryError('Unsupported statement: ' + type(node).__name__)

    def run(self, source, record):
        if len(source.encode()) > MAX_SOURCE:
            raise QueryError('Resolver source too large')
        tree = ast.parse(source)
        if sum(1 for _ in ast.walk(tree)) > 2048:
            raise QueryError('Resolver syntax too large')
        functions = []
        for node in tree.body:
            if isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant) and isinstance(node.value.value, str): continue
            if isinstance(node, ast.Import) and all(n.name == 'json' and n.asname is None for n in node.names): continue
            if isinstance(node, ast.ImportFrom) and node.module == 'pathlib' and node.level == 0 and [(n.name,n.asname) for n in node.names] == [('Path',None)]: continue
            if isinstance(node, ast.FunctionDef) and node.name == 'resolve': functions.append(node); continue
            raise QueryError('Only json, Path and resolve(root, record) are supported')
        if len(functions) != 1:
            raise QueryError('Define exactly one resolve(root, record) function')
        func = functions[0]
        if func.decorator_list or func.args.defaults or func.args.kwonlyargs or func.args.posonlyargs or func.args.vararg or func.args.kwarg or [a.arg for a in func.args.args] != ['root','record']:
            raise QueryError('Expected resolve(root, record) without decorators or defaults')
        try:
            self.statements(func.body, {'root': str(self.root), 'record': record})
        except Returned as result:
            if not isinstance(result.value, str) or len(result.value) > 4096:
                raise QueryError('Return a relative path string')
            return result.value
        raise QueryError('Resolver returned no path')


def main():
    try:
        request = json.loads(sys.stdin.buffer.read(MAX_SOURCE))
        script = Path(sys.argv[1])
        with script.open('rb') as stream:
            source = stream.read(MAX_SOURCE + 1)
        value = Query(request['root']).run(source.decode('utf-8'), request['record'])
        result = {'ok': True, 'path': value}
    except FileNotFoundError as error:
        result = {'ok': False, 'kind': 'missing', 'message': str(error)[:2000]}
    except Exception as error:
        result = {'ok': False, 'kind': 'error', 'type': type(error).__name__, 'message': str(error)[:2000]}
    print(json.dumps(result), flush=True)


if __name__ == '__main__': main()

"""Isolated synthetic data-fault plugin; generation/rewards/PPO stay native.

Fault injection is deliberately confined to a prepared backing store. Missing
files become native ABORTED samples; the native check_no_aborted filter drops
their groups and resamples. Other I/O and content errors are fatal.
"""
import json
import math
import os
from pathlib import Path
import time

_SOURCE = None


def write_evaluation(directory, rollout_id, last_training_step, data):
    phase = 'before_train' if last_training_step < 0 else f'after_step_{rollout_id:07d}'
    path = Path(directory) / f'eval_{phase}.json'
    serialized = {}
    for name, values in data.items():
        serialized[name] = {
            'rewards': values['rewards'], 'truncated': values['truncated'],
            'samples': [{'index': s.index, 'prompt': s.prompt, 'label': s.label,
                         'response': s.response, 'response_length': s.response_length,
                         'reward': s.reward, 'status': s.status.value, 'metadata': s.metadata}
                        for s in values['samples']],
        }
    with path.open('x') as stream:
        json.dump(serialized, stream, ensure_ascii=False, allow_nan=False)
        stream.write('\n')
    return path


def summarize(reads, admitted):
    if any(r['outcome'] not in ('ok', 'missing') for r in reads):
        raise ValueError('Unknown file-read outcome')
    if any(r['difficulty'] not in ('easy', 'hard') for r in [*reads, *admitted]):
        raise ValueError('Unknown difficulty')
    rewards = [float(row['reward']) for row in admitted]
    if any(not math.isfinite(r) or not 0 <= r <= 1 for r in rewards):
        raise ValueError('Expected finite, unmodified 0/1 math rewards')
    ok = sum(r['outcome'] == 'ok' for r in reads)
    aborted = len(reads) - ok
    if not admitted or ok < len(admitted):
        raise ValueError('Admitted samples must have successful file reads')
    result = {
        'data/read_attempts': len(reads),
        'data/abort_count': aborted,
        'data/abort_rate': aborted / len(reads),
        'data/admitted_count': len(admitted),
        'data/read_ok_not_admitted': ok - len(admitted),
        'data/admitted_hard_fraction': sum(r['difficulty'] == 'hard' for r in admitted) / len(admitted),
        'data/reward_sum': sum(rewards),
        'data/survivor_reward_mean': sum(rewards) / len(rewards),
        # Explicit diagnostic denominator: extra completed/cancelled reads are
        # not graded as failures. This is reward admitted per read attempt.
        'data/admitted_reward_per_read_attempt': sum(rewards) / len(reads),
    }
    for group in ['easy', 'hard']:
        rr = [float(r['reward']) for r in admitted if r['difficulty'] == group]
        result[f'data/admitted_{group}'] = len(rr)
        result[f'data/attempted_{group}'] = sum(r['difficulty'] == group for r in reads)
        result[f'data/abort_{group}'] = sum(r['difficulty'] == group and r['outcome'] == 'missing' for r in reads)
        if rr:
            result[f'data/reward_{group}_mean'] = sum(rr) / len(rr)
    return result


def terminal_metrics(reads, terminals, admitted_indices, requested_indices):
    outcomes = {row['index']: row for row in terminals}
    if len(outcomes) != len(terminals) or set(outcomes) != set(requested_indices):
        raise ValueError('Missing or duplicate terminal outcomes')
    by_read = {row['index']: row for row in reads}
    if len(by_read) != len(reads) or not set(by_read) <= set(outcomes):
        raise ValueError('Read attempts lack unique terminal outcomes')
    admitted = set(admitted_indices)
    if not admitted <= set(by_read):
        raise ValueError('Admitted samples lack read attempts')
    scores = []
    generation_aborts = pre_read_cancelled = surplus_scored = truncated = 0
    for index, row in outcomes.items():
        status, reward = row['status'], row['reward']
        if status in ('completed', 'truncated'):
            if index not in by_read or by_read[index]['outcome'] != 'ok':
                raise ValueError('Scored sample lacks successful read')
            if reward not in (0, 1):
                raise ValueError('Expected raw binary math reward')
            scores.append(float(reward))
            surplus_scored += index not in admitted
            truncated += status == 'truncated'
        elif status in ('aborted', 'pending'):
            if reward is not None or index in admitted:
                raise ValueError('Aborted/pending sample was graded or admitted')
            if index not in by_read:
                pre_read_cancelled += 1
            elif by_read[index]['outcome'] == 'ok':
                generation_aborts += 1
        else:
            raise ValueError('Unexpected generation terminal status: ' + status)
    if not reads:
        raise ValueError('No file reads')
    return {'data/terminal_count': len(outcomes), 'data/requested_count': len(requested_indices),
            'data/generation_abort_count': generation_aborts,
            'data/scheduler_cancel_before_read': pre_read_cancelled,
            'data/scored_count': len(scores), 'data/scored_not_admitted': surplus_scored,
            'data/truncated_count': truncated, 'data/all_scored_reward_sum': sum(scores),
            'data/reward_per_read_attempt': sum(scores) / len(reads)}


def install_outcome_observer():
    """Observe the native group result after grading, including drained tasks."""
    from miles.rollout import sglang_rollout as native
    original = native.generate_and_rm_group
    if getattr(original, '_relocation_observer', False):
        return

    async def observed(args, group, sampling_params, evaluation=False):
        result = await original(args, group, sampling_params, evaluation=evaluation)
        if not evaluation:
            if _SOURCE is None:
                raise RuntimeError('Missing source for terminal observation')
            for sample in result:
                record = {'id': sample.metadata['backing_ref']['id'], 'index': sample.index,
                          'group_index': sample.group_index, 'difficulty': sample.metadata['difficulty'],
                          'status': sample.status.value, 'reward': sample.reward,
                          'response_length': sample.response_length}
                _SOURCE.terminals.append(_SOURCE.emit('terminal', **record,
                                                      response=sample.response, label=sample.label))
        return result
    observed._relocation_observer = True
    native.generate_and_rm_group = observed


class BackedMathSource:
    """Native datasource contract, storing references instead of prompt bodies."""
    def __init__(self, args):
        from store import SceneStore
        global _SOURCE
        self.args = args
        self.store = SceneStore(Path(os.environ['RELOCATION_DATA']))
        self.output = Path(os.environ['RELOCATION_OUTPUT'])
        self.output.mkdir(parents=True, exist_ok=True)
        self.arm = os.environ['RELOCATION_ARM']
        if self.arm != 'incident':
            raise ValueError('Unknown experiment arm')
        self.at = int(os.environ['RELOCATION_AT'])
        if self.at <= 0:
            raise ValueError('Migration must occur after training has begun')
        self.dataset = self.store.rows
        self.cursor = self.sample_index = self.group_index = 0
        self.step = -1
        self.requests = 0
        self.reads = []
        self.terminals = []
        self.requested_indices = set()
        self.metadata = {}
        _SOURCE = self

    def emit(self, kind, **fields):
        event = {'kind': kind, 'step': self.step, 'arm': self.arm,
                 'wall_time': time.time(), **fields}
        with (self.output / 'events.jsonl').open('a') as f:
            f.write(json.dumps(event, ensure_ascii=False, allow_nan=False) + '\n')
        return event

    def begin(self, step):
        self.step, self.requests, self.reads = step, 0, []
        self.terminals, self.requested_indices = [], set()
        self.emit('rollout_begin', cursor=self.cursor)

    def get_samples(self, num_samples):
        from miles.utils.types import Sample
        self.requests += num_samples
        # Bound resampling even if every backing file is unavailable.
        if self.requests > 16 * self.args.rollout_batch_size:
            raise RuntimeError('Backing-file retry budget exhausted')
        groups = []
        for _ in range(num_samples):
            row = dict(self.store.rows[self.cursor % len(self.store.rows)])
            self.cursor += 1
            group = []
            for _ in range(self.args.n_samples_per_prompt):
                group.append(Sample(group_index=self.group_index, index=self.sample_index,
                                    metadata={'backing_ref': row, 'difficulty': row['difficulty']}))
                self.requested_indices.add(self.sample_index)
                self.sample_index += 1
            self.group_index += 1
            groups.append(group)
        return groups

    def add_samples(self, samples):
        if samples:
            raise RuntimeError('Partial-rollout buffers must be disabled for this case')

    def save(self, rollout_id):
        target = Path(self.args.save) / 'rollout' / f'data_state_{rollout_id}.json'
        target.parent.mkdir(parents=True, exist_ok=True)
        state = {'cursor': self.cursor, 'sample_index': self.sample_index,
                 'group_index': self.group_index, 'step': self.step, 'arm': self.arm}
        temp = target.with_suffix('.tmp')
        temp.write_text(json.dumps(state) + '\n')
        temp.replace(target)

    def load(self, rollout_id=None):
        if not self.args.load or rollout_id is None:
            return
        target = Path(self.args.load) / 'rollout' / f'data_state_{rollout_id}.json'
        if not target.exists():
            if rollout_id >= 0 and Path(self.args.load, 'latest_checkpointed_iteration.txt').exists():
                raise RuntimeError('Checkpoint is missing matching datasource state')
            return
        state = json.loads(target.read_text())
        self.cursor, self.sample_index, self.group_index = (state[k] for k in ('cursor', 'sample_index', 'group_index'))
        self.step = state['step']
        if self.step != 3 or self.cursor != 32 or self.sample_index != 64:
            raise ValueError('Unexpected checkpoint datasource cursor')
        self.emit('datasource_restored', cursor=self.cursor, sample_index=self.sample_index)

    def get_metadata(self):
        return self.metadata

    def update_metadata(self, metadata):
        self.metadata.update(metadata)

    def get_buffer_length(self):
        return 0


async def generate(args, sample, sampling_params, evaluation=False):
    from miles.rollout.sglang_rollout import GenerateState, generate as native_generate
    from miles.utils.types import Sample
    reference = sample.metadata.get('backing_ref')
    if reference is None:
        # Fixed evaluation data is inline, outside the migrated backing store.
        if not evaluation:
            raise ValueError('Training samples require a backing reference')
        return await native_generate(args, sample, sampling_params)
    source = _SOURCE
    if source is None or evaluation:
        raise RuntimeError('Invalid lazy datasource context')
    fields = {'id': reference['id'], 'index': sample.index,
              'group_index': sample.group_index, 'difficulty': reference['difficulty'],
              'path': reference['path']}
    try:
        payload = source.store.read(reference,sample_index=sample.index,step=source.step)
    except FileNotFoundError as error:
        source.reads.append(source.emit('read', outcome='missing', errno=error.errno, **fields))
        sample.status = Sample.Status.ABORTED
        sample.metadata['env_error'] = 'backing_file_unavailable'
        return sample
    source.reads.append(source.emit('read', outcome='ok', sha256=reference['sha256'], **fields))
    state = GenerateState(args)
    sample.prompt = state.tokenizer.apply_chat_template(
        payload['prompt'], tokenize=False, add_generation_prompt=True,
        **(args.apply_chat_template_kwargs or {}))
    sample.label = payload['label']
    sample.metadata.update(payload.get('metadata', {}))
    return await native_generate(args, sample, sampling_params)


def generate_rollout(args, rollout_id, data_source, evaluation=False):
    from miles.rollout.sglang_rollout import generate_rollout as native_rollout
    if evaluation:
        output = native_rollout(args, rollout_id, data_source, evaluation=True)
        # Full native evaluation result is retained in the private run directory.
        write_evaluation(data_source.output, rollout_id, data_source.step, output.data)
        return output
    if args.partial_rollout or args.over_sampling_batch_size != args.rollout_batch_size:
        raise ValueError('This case requires no partial buffers and equal initial/target batch sizes')
    if args.dynamic_sampling_filter_path != 'miles.rollout.filter_hub.dynamic_sampling_filters.check_no_aborted':
        raise ValueError('Use the native aborted-group filter without reward filtering')
    if rollout_id < 4:
        raise ValueError('Incident continuation must start from checkpoint3')
    data_source.begin(rollout_id)
    install_outcome_observer()
    output = native_rollout(args, rollout_id, data_source, evaluation=False)
    admitted = []
    for group in output.samples:
        for sample in group:
            if sample.status.name not in ('COMPLETED', 'TRUNCATED'):
                raise ValueError('Non-generated sample reached training')
            record = {'id': sample.metadata['backing_ref']['id'], 'index': sample.index,
                      'group_index': sample.group_index, 'difficulty': sample.metadata['difficulty'],
                      'reward': sample.reward, 'status': sample.status.value,
                      'response_length': sample.response_length}
            admitted.append(record)
            data_source.emit('admitted', **record, response=sample.response, label=sample.label)
    metrics = summarize(data_source.reads, admitted)
    metrics.update(terminal_metrics(data_source.reads, data_source.terminals,
                                   [row['index'] for row in admitted], data_source.requested_indices))
    output.metrics = {**(output.metrics or {}), **metrics}
    data_source.emit('rollout_end', metrics=metrics)
    print('DATA_RELOCATION_METRICS ' + json.dumps({'step': rollout_id, **metrics}), flush=True)
    return output

